package com.lootpop;

public enum BackgroundMode
{
    SOLID("Solid"),
    TRANSPARENT("Transparent");

    private final String displayName;

    BackgroundMode(String displayName)
    {
        this.displayName = displayName;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.lootpop;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class LootDisplayItem
{
    private final int itemId;
    private final int quantity;
    private final long unitPrice;

    LootDisplayItem(int itemId, int quantity, long unitPrice)
    {
        this.itemId = itemId;
        this.quantity = quantity;
        this.unitPrice = unitPrice;
    }

    int getItemId()
    {
        return itemId;
    }

    int getQuantity()
    {
        return quantity;
    }

    long getUnitPrice()
    {
        return unitPrice;
    }

    long getTotalValue()
    {
        return unitPrice * quantity;
    }

    static List<LootDisplayItem> mergeDuplicates(List<LootDisplayItem> items)
    {
        Map<Integer, LootDisplayItem> merged = new LinkedHashMap<>();
        for (LootDisplayItem item : items)
        {
            LootDisplayItem existing = merged.get(item.itemId);
            if (existing == null)
            {
                merged.put(item.itemId, item);
                continue;
            }

            long combinedQuantity = (long) existing.quantity + item.quantity;
            int quantity = (int) Math.min(Integer.MAX_VALUE, combinedQuantity);
            merged.put(item.itemId, new LootDisplayItem(item.itemId, quantity, existing.unitPrice));
        }
        return new ArrayList<>(merged.values());
    }
}

package com.lootpop;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class LootNotification
{
    private final String sourceName;
    private final List<LootDisplayItem> items;
    private final long totalValue;
    private final long createdAtMillis;

    LootNotification(String sourceName, List<LootDisplayItem> items, long totalValue, long createdAtMillis)
    {
        this.sourceName = sourceName;
        this.items = Collections.unmodifiableList(new ArrayList<>(items));
        this.totalValue = totalValue;
        this.createdAtMillis = createdAtMillis;
    }

    String getSourceName()
    {
        return sourceName;
    }

    List<LootDisplayItem> getItems()
    {
        return items;
    }

    long getTotalValue()
    {
        return totalValue;
    }

    long getAgeMillis(long nowMillis)
    {
        return Math.max(0L, nowMillis - createdAtMillis);
    }

    float getAlpha(long nowMillis, int displayDuration, int fadeDuration)
    {
        long age = getAgeMillis(nowMillis);
        if (age <= displayDuration)
        {
            return 1.0f;
        }

        if (fadeDuration <= 0)
        {
            return 0.0f;
        }

        float progress = (age - displayDuration) / (float) fadeDuration;
        return Math.max(0.0f, 1.0f - progress);
    }

    boolean isExpired(long nowMillis, int displayDuration, int fadeDuration)
    {
        return nowMillis - createdAtMillis > (long) displayDuration + fadeDuration;
    }
}

